namespace Scheduler.Core;
public interface ITaskHandler{bool CanHandle(WorkTask task);Task ExecuteAsync(WorkTask task,CancellationToken token);}
public sealed class DelegateTaskHandler(Func<WorkTask,CancellationToken,Task> action):ITaskHandler{public bool CanHandle(WorkTask _)=>true;public Task ExecuteAsync(WorkTask task,CancellationToken token)=>action(task,token);}
public sealed class SchedulerEngine(TaskCatalog catalog,IEnumerable<ITaskHandler> handlers)
{public async Task<IReadOnlyList<string>> RunAsync(IReadOnlyList<Worker> workers,CancellationToken token=default){var done=new List<string>();while(true){var graph=new DependencyGraph(catalog);var ready=new PriorityQueue<WorkTask,(int Priority,string Id)>();foreach(var id in graph.ReadyIds()){var task=catalog[id];if(task.Status==Status.Pending)catalog[id]=task=task.Transition(Status.Ready);ready.Enqueue(task,(-task.Priority,task.Id));}var progressed=false;while(ready.TryDequeue(out var task,out _)){token.ThrowIfCancellationRequested();if(!workers.Any(w=>w.CanRun(task)))continue;var handler=handlers.FirstOrDefault(h=>h.CanHandle(task))??throw new InvalidOperationException("handler");progressed=true;catalog[task.Id]=task=task.Transition(Status.Running);try{await handler.ExecuteAsync(task,token);catalog[task.Id]=task.Transition(Status.Succeeded);}catch when(!token.IsCancellationRequested){catalog[task.Id]=task.Transition(Status.Failed);}done.Add(task.Id);}if(!progressed)break;}return done;}}
